package com.akitaattribute.mobfarmblock.behavior;
import com.akitaattribute.mobfarmblock.MobFarmBlockMod; import net.minecraft.item.*; import net.minecraft.entity.EquipmentSlot; import net.minecraft.util.ActionResult; import net.minecraft.util.DyeColor;
public class SheepBehavior extends GenericMobBehavior { static final long WOOL_COOLDOWN=12000; public ActionResult interact(MobFarmContext c){var h=c.heldItem(); var st=c.stored().state; if(h.isOf(Items.SHEARS)){long now=c.level().getTime(); boolean has=st.contains("hasWool")?st.getBoolean("hasWool"):true; var id=MobFarmBlockMod.id("wool"); if(has && c.stored().ready(id,now)){BehaviorUtil.output(c,new ItemStack(wool(st.getString("sheepColor")))); st.putBoolean("hasWool",false); st.putLong("nextWoolReadyAt",now+WOOL_COOLDOWN); c.stored().setCooldown(id,now,WOOL_COOLDOWN); h.damage(1,c.player(),EquipmentSlot.MAINHAND); return ActionResult.SUCCESS;}} if(h.getItem() instanceof DyeItem dye){h.decrement(1); st.putString("sheepColor",dye.getColor().getName()); c.stored().display=new com.akitaattribute.mobfarmblock.mob.DisplaySnapshot(c.stored().display.entityTypeId(),c.stored().display.textureId(),c.stored().display.variantKey(),dye.getColor().getName(),c.stored().display.baby(),c.stored().display.scale()); return ActionResult.SUCCESS;} if(h.isOf(Items.WHEAT)){h.decrement(1); c.stored().count++; return ActionResult.SUCCESS;} return ActionResult.PASS;} private static Item wool(String c){DyeColor d=DyeColor.byName(c,DyeColor.WHITE); return switch(d){case BLACK->Items.BLACK_WOOL;case BLUE->Items.BLUE_WOOL;case BROWN->Items.BROWN_WOOL;case CYAN->Items.CYAN_WOOL;case GRAY->Items.GRAY_WOOL;case GREEN->Items.GREEN_WOOL;case LIGHT_BLUE->Items.LIGHT_BLUE_WOOL;case LIGHT_GRAY->Items.LIGHT_GRAY_WOOL;case LIME->Items.LIME_WOOL;case MAGENTA->Items.MAGENTA_WOOL;case ORANGE->Items.ORANGE_WOOL;case PINK->Items.PINK_WOOL;case PURPLE->Items.PURPLE_WOOL;case RED->Items.RED_WOOL;case YELLOW->Items.YELLOW_WOOL;default->Items.WHITE_WOOL;};} }
